/// <summary>
/// COC extension class for <c>FreeTextInvoice</c> class 
/// </summary>

[ExtensionOf(classStr(FreeTextInvoiceDP))]
internal final class METFreeTextInvoiceDP_Extension
{
    public METRebateInvoiceDetailsTmp metRebateInvoiceDetailsTmp;
    public TAMRebateDeal rebateDeal;

}

